import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.1lnE8eph.js";const g=JSON.parse('{"title":"Floating Select and Table Sorting","description":"","frontmatter":{},"headers":[],"relativePath":"specs/002-select-and-sorting.md","filePath":"specs/002-select-and-sorting.md"}'),l={name:"specs/002-select-and-sorting.md"};function o(s,e,r,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="floating-select-and-table-sorting" tabindex="-1">Floating Select and Table Sorting <a class="header-anchor" href="#floating-select-and-table-sorting" aria-label="Permalink to &quot;Floating Select and Table Sorting&quot;">​</a></h1><h2 id="_1-scope" tabindex="-1">1. Scope <a class="header-anchor" href="#_1-scope" aria-label="Permalink to &quot;1. Scope&quot;">​</a></h2><p>Replace the design system&#39;s native select with a reusable Floating UI select and add toolbar-driven sorting to the main bus schedule.</p><h2 id="_2-design-system-select" tabindex="-1">2. Design-system select <a class="header-anchor" href="#_2-design-system-select" aria-label="Permalink to &quot;2. Design-system select&quot;">​</a></h2><ul><li>Implement the select using the already-installed Floating UI React dependency.</li><li>Replace every existing design-system select usage, including the dashboard theme selector, time-window selector, documentation controls, and dialog examples.</li><li>Expose typed options, controlled value/change props, and an optional default value for uncontrolled usage.</li><li>Preserve accessible labels, selected and disabled states, theme styling, and named form values.</li><li>Support pointer selection, keyboard opening/navigation/selection, typeahead, Escape/outside dismissal, and focus restoration.</li><li>Position the listbox in a portal, keep it within the viewport, and allow scrolling when needed.</li><li>Do not retain a native select as the visible control.</li></ul><h2 id="_3-shared-table-sorting-api" tabindex="-1">3. Shared table sorting API <a class="header-anchor" href="#_3-shared-table-sorting-api" aria-label="Permalink to &quot;3. Shared table sorting API&quot;">​</a></h2><ul><li>Enable sorting through the existing TanStack Table v9 API and shared table features.</li><li>Accept default sorting through the table options&#39; <code>initialState.sorting</code> property.</li><li>Render rows in their original input order when default sorting is not supplied.</li><li>Support ascending and descending sorting and clearing back to the original input order.</li><li>Derive sortable fields from column definitions; do not maintain a separate toolbar column list.</li><li>Honor column-level sorting availability, comparator, and initial-direction settings.</li><li>Use the field&#39;s standard initial order when sorting is first applied: <ul><li>Text and identifiers: ascending, with natural ordering for numbered identifiers.</li><li>Numeric counts: descending.</li><li>Schedule times: chronological ascending.</li></ul></li><li>Sort the Stops column by stop count, not the underlying array.</li><li>Preserve row identity, selection, Gantt rendering, and resizing when order changes.</li></ul><h2 id="_4-schedule-toolbar-and-column-headers" tabindex="-1">4. Schedule toolbar and column headers <a class="header-anchor" href="#_4-schedule-toolbar-and-column-headers" aria-label="Permalink to &quot;4. Schedule toolbar and column headers&quot;">​</a></h2><ul><li>Add a <strong>Sort by</strong> dropdown to the main schedule toolbar.</li><li>List sortable columns using their column-definition labels.</li><li>Include an <strong>Unsorted</strong> option that restores original input order.</li><li>Render a sort-order button directly beside the dropdown.</li><li>Disable the order button while unsorted.</li><li>Show the current direction and let the button toggle ascending/descending order.</li><li>Do not add sorting buttons or click-to-sort interactions to column headers by default.</li><li>Show only a direction indicator in the active column header and expose <code>aria-sort</code>.</li><li>Keep column resize separators functional and toolbar controls usable in narrow panes.</li></ul><h2 id="_5-implementation-constraints" tabindex="-1">5. Implementation constraints <a class="header-anchor" href="#_5-implementation-constraints" aria-label="Permalink to &quot;5. Implementation constraints&quot;">​</a></h2><ul><li>Keep reusable presentation and styles in the design-system package.</li><li>Reuse installed dependencies and the existing shared table implementation.</li><li>Define new fixed behavioral/default constants in enums when they are not supplied through props.</li><li>Update directly related usage documentation and regression tests.</li></ul><h2 id="_6-validation-and-delivery" tabindex="-1">6. Validation and delivery <a class="header-anchor" href="#_6-validation-and-delivery" aria-label="Permalink to &quot;6. Validation and delivery&quot;">​</a></h2><ul><li>Verify controlled and uncontrolled select rendering, disabled behavior, keyboard interaction, dismissal, theme propagation, and migrated usages.</li><li>Verify unsorted/default-sorted tables, field-specific initial directions, order toggling, reset, and header indicators without header sorting buttons.</li><li>Run existing design-system/transit tests, strict type checking, and a production build.</li><li>Work on a new feature branch and create a new pull request against <code>main</code>.</li></ul>',13)])])}const p=t(l,[["render",o]]);export{g as __pageData,p as default};
